/* From Uiverse.io by codebykay101 - Tags: animation, form, contact, hover effect, css effect */
.__UIV_SCOPE__ .container {
  width: 350px;
  height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border-radius: 3px;
  border: 1px solid #396afc;
  background: linear-gradient(to right, #005c97, #363795);
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
}

.__UIV_SCOPE__ .container form .descr {
  font-size: 20px;
  font-weight: 500;
  color: #e8e8e8;
  margin-bottom: 25px;
  margin-top: 25px;
  text-align: center;
}

.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .input, .__UIV_SCOPE__ textarea {
  margin: 1em 0 1em 0;
  width: 300px;
  position: relative;
}

.__UIV_SCOPE__ .input input, .__UIV_SCOPE__ textarea {
  font-size: 100%;
  padding: 0.7em;
  outline: none;
  color: #e8e8e8;
  border: none;
  border-bottom: 2px solid #e8e8e8;
  background: transparent;
  border-radius: none;
  width: 100%;
  resize: none;
}

.__UIV_SCOPE__ .input label {
  font-size: 100%;
  position: absolute;
  left: 0;
  color: #e8e8e8;
  padding: 0.7em;
  margin-left: 0.1em;
  pointer-events: none;
  transition: all 0.5s ease;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .input :is(input:focus, input:valid)~label {
  transform: translateY(-50%) scale(.9);
  margin: 0em;
  padding: 0.4em;
  background: transparent;
}

.__UIV_SCOPE__ .input textarea:focus ~ label,
.__UIV_SCOPE__ .input textarea:valid ~ label {
  transform: translateY(-50%) scale(.9);
  margin: 0em;
  padding: 0.4em;
  background: transparent;
}

.__UIV_SCOPE__ .inputGroup :is(input:focus, input:valid) {
  border-color: rgb(37, 37, 211);
}

.__UIV_SCOPE__ .form button {
  color: #e8e8e8;
  font-size: 15px;
  align-self: flex-start;
  padding: 0.6em;
  border: none;
  cursor: pointer;
  margin-bottom: 50px;
  background: transparent;
  transition: all 0.3s ease-in-out;
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ .form button:before {
  content: "";
  position: absolute;
  bottom: 100%;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: #e8e8e8;
  opacity: 0;
  transition: opacity 0.3s ease-in-out;
}

.__UIV_SCOPE__ .form button:hover:before {
  opacity: 0.2;
}

.__UIV_SCOPE__ .form button:hover {
  transform: translateY(-3px);
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
}
